-- c010-v002: – Же входящий через – дверь, пастырь есть – овец.
-- c010-v003: Ему – привратник открывает, и – овцы – голоса его слушают, и – своих овец зовёт по имени, и выводит их.
-- c010-v004: Когда – своих всех выведет перед ними, идёт; и – овцы за–ним следуют, потому–что знают – голос его.
