-- c010-v006: Эту – притчу сказал им – Иисус; те же не узнали что было, что говорил им.
-- c010-v007: Сказал итак снова им – Иисус, Истинно истинно говорю вам, что Я есмь – дверь – овец.
-- c010-v008: Все кто пришли до Меня, воры суть и разбойники; но не послушали их – овцы.
-- c010-v009: Я есмь – дверь; через Меня если кто войдёт спасётся, и войдёт, и выйдет, и пастбище найдёт.
-- c010-v010: – Вор не приходит если не чтобы украсть, и убить, и погубить. Я пришёл чтобы жизнь имели, и изобильно имели.
-- c010-v011: Я есмь – Пастырь – добрый. – Пастырь – добрый, – душу Свою полагает за – овец:
-- c010-v012: – Наёмник и не сущий пастырем, которого не суть – овцы своими, видит – волка приходящего, и оставляет – овец, и бежит; и – волк хватает их, и рассеивает,
-- c010-v013: потому–что наёмник есть, и не заботится ему о – овцах.
-- c010-v014: Я есмь – Пастырь – добрый; и знаю – Моих, и знают Меня – Мои.
-- c010-v015: Как знает Меня – Отец, и–Я знаю – Отца; и – душу Мою полагаю за – овец.
-- c010-v016: И другие овцы имею, которые не суть из – двора этого; и–тех должен Я привести, и – голоса Моего услышат; и станут одно стадо, один Пастырь.
-- c010-v017: Из–за этого, Меня – Отец любит, потому–что Я полагаю – душу Мою, чтобы снова принять её.
-- c010-v018: Никто берёт её от Меня, но Я полагаю её от Себя–Самого. Власть имею положить её, и власть имею снова принять её. Эту – заповедь получил от – Отца Моего.
-- c010-v019: Разделение снова сделалось среди – Иудеев, из–за – слов этих;
-- c010-v020: говорили же многие из них, Беса имеет, и безумствует; что Его слушаете?
-- c010-v021: Другие говорили, Эти – слова не суть бесноватого. Разве бес может слепых глаза открывать?
-- c010-v022: Было тогда – обновление, в – Иерусалиме. Зима была.
-- c010-v023: И ходил – Иисус в – храме, в – притворе – Соломоновом.
-- c010-v024: Обступили итак Его – Иудеи, и говорили Ему, Доколе когда – душу нашу держишь? Если Ты есть – Христос, скажи нам открыто.
-- c010-v025: Ответил им – Иисус, Сказал вам, и не верите. – Дела которые Я творю во – имя – Отца Моего, они свидетельствуют о Мне.
-- c010-v026: Но вы не верите, потому–что не есть из – овец – Моих.
-- c010-v027: – Овцы – Мои, – голоса Моего слушают, и–Я знаю их, и следуют за–Мной;
-- c010-v028: и–Я даю им жизнь вечную; и не ни погибнут, во – век, и не похитит кто их из – руки Моей.
-- c010-v029: – Отец Мой Который дал Мне, всех больше есть, и никто может похищать из – руки – Отца.
-- c010-v030: Я и – Отец одно есмы.
-- c010-v031: Подняли итак снова камни – Иудеи, чтобы побить–камнями Его.
-- c010-v032: Ответил им – Иисус, Многие дела показал вам добрые от – Отца; за какое из–них дело, Меня побиваете–камнями?
-- c010-v033: Ответили Ему – Иудеи, За доброе дело не побиваем–камнями Тебя, но за богохульство, и потому–что Ты, человек будучи, делаешь Себя–Самого Богом.
-- c010-v034: Ответил им – Иисус, Не есть написано в – законе вашем что, Я сказал, Боги есть?
