-- c010-v036: Которого – Отец освятил и послал в – мир, вы говорите что, Богохульствуешь, потому–что сказал, Сын – Божий есмь?
-- c010-v037: Если не творю – дела – Отца Моего, не верьте Мне.
-- c010-v038: Если же творю, если–и Мне не верите, – делам верьте, чтобы узнали, и знали что во Мне – Отец, и–Я в – Отце.
